import{_ as e,o as a,c as o,a0 as r}from"./chunks/framework.DCToIpx6.js";const b=JSON.parse('{"title":"REQ-COL-FILTERABLE — Filterable Columns","description":"","frontmatter":{},"headers":[],"relativePath":"tests/test-cases/dynamic-column-config/REQ-COL-FILTERABLE.md","filePath":"tests/test-cases/dynamic-column-config/REQ-COL-FILTERABLE.md"}'),d={name:"tests/test-cases/dynamic-column-config/REQ-COL-FILTERABLE.md"};function l(n,t,s,i,c,u){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="req-col-filterable-—-filterable-columns" tabindex="-1">REQ-COL-FILTERABLE — Filterable Columns <a class="header-anchor" href="#req-col-filterable-—-filterable-columns" aria-label="Permalink to &quot;REQ-COL-FILTERABLE — Filterable Columns&quot;">​</a></h1><p><strong>Requerimiento:</strong> El filtro global DEBE buscar solo en columnas donde <code>filterable !== false</code>. Columnas con <code>filterable: false</code> DEBEN ser excluidas. Cuando <code>filterable</code> es <code>undefined</code>, la columna DEBE incluirse por defecto.</p><hr><h2 id="tc-col-filterable-01-filterable-false-excluye-columna-de-busqueda" tabindex="-1">TC-COL-FILTERABLE-01: filterable: false excluye columna de búsqueda <a class="header-anchor" href="#tc-col-filterable-01-filterable-false-excluye-columna-de-busqueda" aria-label="Permalink to &quot;TC-COL-FILTERABLE-01: filterable: false excluye columna de búsqueda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-FILTERABLE-01</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-FILTERABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columnas: <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}, {key: &#39;notes&#39;, header: &#39;Notes&#39;, filterable: false}]</code>. Filas: <code>[{name: &#39;Alice&#39;, notes: &#39;confidential&#39;}]</code>.</td></tr><tr><td><strong>Pasos</strong></td><td>1. Escribir &quot;confidential&quot; en el filtro global<br>2. Verificar filas mostradas</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>No se muestran filas. La columna <code>notes</code> fue excluida de la búsqueda, por lo que &quot;confidential&quot; no encontró match.</td></tr></tbody></table><hr><h2 id="tc-col-filterable-02-filterable-false-no-oculta-datos-del-ui" tabindex="-1">TC-COL-FILTERABLE-02: filterable: false no oculta datos del UI <a class="header-anchor" href="#tc-col-filterable-02-filterable-false-no-oculta-datos-del-ui" aria-label="Permalink to &quot;TC-COL-FILTERABLE-02: filterable: false no oculta datos del UI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-FILTERABLE-02</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-FILTERABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path</td></tr><tr><td><strong>Precondiciones</strong></td><td>Misma config que TC-COL-FILTERABLE-01</td></tr><tr><td><strong>Pasos</strong></td><td>1. Escribir &quot;Alice&quot; en el filtro global<br>2. Verificar filas mostradas</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>La fila <code>Alice</code> se muestra porque la columna <code>name</code> (filterable por defecto) contiene &quot;Alice&quot;. La columna <code>notes</code> se renderiza visualmente pero no participa en la búsqueda.</td></tr></tbody></table><hr><h2 id="tc-col-filterable-03-filterable-undefined-incluye-columna-por-defecto" tabindex="-1">TC-COL-FILTERABLE-03: filterable undefined incluye columna por defecto <a class="header-anchor" href="#tc-col-filterable-03-filterable-undefined-incluye-columna-por-defecto" aria-label="Permalink to &quot;TC-COL-FILTERABLE-03: filterable undefined incluye columna por defecto&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-FILTERABLE-03</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-FILTERABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path (borde)</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columnas sin propiedad <code>filterable</code> (o <code>filterable: undefined</code>). Filas con datos variados.</td></tr><tr><td><strong>Pasos</strong></td><td>1. Escribir un término que exista en cualquier columna<br>2. Verificar que la fila correspondiente aparece</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>Todas las columnas participan en el filtro global. La fila con el término buscado aparece.</td></tr></tbody></table><hr><h2 id="tc-col-filterable-04-todas-las-columnas-con-filterable-false-—-filtro-no-encuentra-nada" tabindex="-1">TC-COL-FILTERABLE-04: Todas las columnas con filterable:false — filtro no encuentra nada <a class="header-anchor" href="#tc-col-filterable-04-todas-las-columnas-con-filterable-false-—-filtro-no-encuentra-nada" aria-label="Permalink to &quot;TC-COL-FILTERABLE-04: Todas las columnas con filterable:false — filtro no encuentra nada&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-FILTERABLE-04</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-FILTERABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Media</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Edge Case</td></tr><tr><td><strong>Precondiciones</strong></td><td>Todas las columnas tienen <code>filterable: false</code></td></tr><tr><td><strong>Pasos</strong></td><td>1. Escribir cualquier término en el filtro global<br>2. Verificar resultado</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>El filtro global no encuentra ninguna fila (no hay columnas searchables). Todas las filas se ocultan independientemente del término.</td></tr></tbody></table><hr><h2 id="tc-col-filterable-05-filtro-global-con-mezcla-filterable-true-false-undefined" tabindex="-1">TC-COL-FILTERABLE-05: Filtro global con mezcla filterable true/false/undefined <a class="header-anchor" href="#tc-col-filterable-05-filtro-global-con-mezcla-filterable-true-false-undefined" aria-label="Permalink to &quot;TC-COL-FILTERABLE-05: Filtro global con mezcla filterable true/false/undefined&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-COL-FILTERABLE-05</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-COL-FILTERABLE</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Integración</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columnas: <code>[{key: &#39;a&#39;}, {key: &#39;b&#39;, filterable: false}, {key: &#39;c&#39;, filterable: true}]</code>. Filas con datos en a, b, c.</td></tr><tr><td><strong>Pasos</strong></td><td>1. Buscar término que solo existe en columna <code>b</code> (filterable: false)<br>2. Buscar término que existe en columna <code>a</code><br>3. Buscar término que existe en columna <code>c</code></td></tr><tr><td><strong>Resultado Esperado</strong></td><td>1. Sin resultados (b está excluida)<br>2. Fila encontrada (a incluida por defecto)<br>3. Fila encontrada (c tiene filterable: true explícito)</td></tr></tbody></table>',17)])])}const g=e(d,[["render",l]]);export{b as __pageData,g as default};
